INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass schnelle Reaktionszeiten immer die Kundenzufriedenheit steigern. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Schnelligkeit erhöht Zufriedenheit"}, {"text": "Nein", "correct": false, "because": "Andere Faktoren spielen auch eine Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich die Kundenzufriedenheit in einem IT-Projekt verbessern will?', 3, '[{"text": "Kundenkommunikation", "correct": true, "because": "Klare Kommunikation fördert Vertrauen"}, {"text": "Schnellere Hardware", "correct": false, "because": "Sekundär"}, {"text": "Bunte Designs", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen erhöhen die Kundenzufriedenheit bei IT-Dienstleistungen?', 5, '[{"text": "Regelmäßige Updates", "correct": true, "because": "Zeigt Engagement"}, {"text": "Schneller Support", "correct": true, "because": "Löst Probleme effizient"}, {"text": "Hohe Preise", "correct": false, "because": "Kann abschrecken"}, {"text": "Weniger Kontakt", "correct": false, "because": "Reduziert Vertrauen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Kundenzufriedenheit hängt von Qualität ab. b) Preis ist immer entscheidend.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Preis nicht immer maßgeblich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich die Kundenzufriedenheit bei Software verbessere?', 4, '[{"text": "Kundenfeedback", "correct": false, "because": "Wichtig für Verbesserung"}, {"text": "Servicequalität", "correct": false, "because": "Entscheidend für Zufriedenheit"}, {"text": "Büroausstattung", "correct": true, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Kundenzufriedenheit nur von Technik abhängt?', 2, '[{"text": "Nein", "correct": true, "because": "Service und Kommunikation zählen auch"}, {"text": "Ja", "correct": false, "because": "Zu einseitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich Kundenzufriedenheit im IT-Support erhöhe?', 3, '[{"text": "Kundenbindung", "correct": true, "because": "Zufriedene Kunden bleiben"}, {"text": "Weniger Support", "correct": false, "because": "Kein primäres Ziel"}, {"text": "Höhere Kosten", "correct": false, "because": "Nicht erwünscht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren fördern die Kundenzufriedenheit bei IT-Projekten?', 5, '[{"text": "Transparenz", "correct": true, "because": "Schafft Vertrauen"}, {"text": "Zuverlässigkeit", "correct": true, "because": "Erfüllt Erwartungen"}, {"text": "Komplexe Prozesse", "correct": false, "because": "Erschwert Nutzung"}, {"text": "Hohe Preise", "correct": false, "because": "Kann unzufrieden machen"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Guter Support steigert Zufriedenheit. b) Kunden erwarten immer kostenlose Dienste. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kostenlosigkeit nicht immer erwartet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Kundenzufriedenheit bei IT-Lösungen zu erhöhen?', 4, '[{"text": "Kundenfeedback", "correct": false, "because": "Liefert Verbesserungshinweise"}, {"text": "Qualitätssicherung", "correct": false, "because": "Sichert Zufriedenheit"}, {"text": "Luxusverpackung", "correct": true, "because": "Kein IT-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hängt Kundenzufriedenheit nur vom Preis ab?', 2, '[{"text": "Nein", "correct": true, "because": "Qualität und Service sind auch wichtig"}, {"text": "Ja", "correct": false, "because": "Zu einseitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt hohe Kundenzufriedenheit in der IT?', 4, '[{"text": "Wiederholungskäufe", "correct": true, "because": "Zufriedene Kunden kehren zurück"}, {"text": "Positive Empfehlungen", "correct": true, "because": "Fördert Neukunden"}, {"text": "Höhere Kosten", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Kundenzufriedenheit nur durch Technik gemessen wird. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Umfragen und Feedback zählen auch"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um die Kundenzufriedenheit bei Software zu steigern?', 3, '[{"text": "Benutzerfreundlichkeit", "correct": true, "because": "Erhöht Zufriedenheit"}, {"text": "Teure Features", "correct": false, "because": "Nicht immer nötig"}, {"text": "Bunte Grafiken", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Feedback verbessert Zufriedenheit. b) Kunden ignorieren Support.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Support wird geschätzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) Wahr"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind bei der Kundenzufriedenheit in der IT entscheidend?', 5, '[{"text": "Reaktionszeit", "correct": true, "because": "Zeigt Servicequalität"}, {"text": "Verlässlichkeit", "correct": true, "because": "Erfüllt Erwartungen"}, {"text": "Luxusverpackung", "correct": false, "because": "Kein IT-Faktor"}, {"text": "Hohe Preise", "correct": false, "because": "Kann abschrecken"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich Kundenzufriedenheit bei IT-Diensten steigere?', 3, '[{"text": "Supportqualität", "correct": false, "because": "Entscheidend für Zufriedenheit"}, {"text": "Kundenkommunikation", "correct": false, "because": "Fördert Vertrauen"}, {"text": "Firmenfarben", "correct": true, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Kundenzufriedenheit immer messbar?', 3, '[{"text": "Ja", "correct": true, "because": "Durch Umfragen und Daten"}, {"text": "Nein", "correct": false, "because": "Messmethoden vorhanden"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Kundenzufriedenheit nur von Technik abhängt?', 2, '[{"text": "Nein", "correct": true, "because": "Service ist ebenso entscheidend"}, {"text": "Ja", "correct": false, "because": "Zu einseitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend, um Kundenzufriedenheit im IT-Bereich zu steigern?', 4, '[{"text": "Kundenorientierung", "correct": true, "because": "Fokussiert auf Bedürfnisse"}, {"text": "Höhere Kosten", "correct": false, "because": "Nicht zwingend"}, {"text": "Luxusdesign", "correct": false, "because": "Irrelevant"}]');
